function publicUrl(token) { return `${window.location.origin}/feedback/product/${token}`; }
function displayAnswer(value) { return Array.isArray(value) ? value.join(", ") : value || "—"; }
const campaignContentDefaults = (campaign = {}) => ({ title: { en: campaign.name || "", zh: "", ms: "" }, description: { en: "", zh: "", ms: "" }, intro_title: { en: "", zh: "", ms: "" }, intro_body: { en: "", zh: "", ms: "" }, thank_you_title: { en: "Thank you", zh: "谢谢您的反馈", ms: "Terima kasih" }, thank_you_body: { en: campaign.thank_you_en || "", zh: campaign.thank_you_zh || "", ms: "" } });
export function productFeedbackCampaignEditorState(campaign = {}) {
  const defaults = campaignContentDefaults(campaign); const content = campaign.content || {};
  return { ...campaign, questions: campaign.questions?.length ? campaign.questions : sambalFeedbackTemplate, content: { ...defaults, ...content, ...Object.fromEntries(Object.keys(defaults).map((key) => [key, { ...defaults[key], ...(content[key] || {}) }])) }, branding: { ...(campaign.branding || {}) } };
}

export default function FactoryProductFeedbackPage({ auth, onNotify }) {
  const [list, setList] = useState({ campaigns: [], finished_goods: [] }); const [detail, setDetail] = useState(null); const [selected, setSelected] = useState(null); const [tab, setTab] = useState("overview"); const [editor, setEditor] = useState(null); const [response, setResponse] = useState(null); const [variantName, setVariantName] = useState(""); const [search, setSearch] = useState(""); const [variant, setVariant] = useState("");
  const can = (permission) => Boolean(auth?.hasPermission?.(permission)); const canEdit = can("factory_product_feedback.edit") || can("factory_product_feedback.manage") || can("factory_product_feedback.create");
  const loadList = async () => { const data = await factoryService.listProductFeedbackAdmin(); setList(data); return data; };
  const openCampaign = async (campaign) => { const data = await factoryService.getProductFeedbackCampaign(campaign.id); setSelected(campaign.id); setDetail(data); setTab("overview"); };
  const editCampaign = async (campaign) => { try { const data = await factoryService.getProductFeedbackCampaign(campaign.id); setEditor(data.campaign); } catch (error) { onNotify?.({ title: "Unable to open campaign", message: error.message, tone: "error" }); } };
  useEffect(() => { loadList().catch((error) => onNotify?.({ title: "Unable to load Product Feedback", message: error.message, tone: "error" })); }, []);
  const campaigns = useMemo(() => (list.campaigns || []).filter((campaign) => `${campaign.name} ${campaign.event_label || ""}`.toLowerCase().includes(search.toLowerCase())), [list, search]);
  const responses = useMemo(() => (detail?.responses || []).filter((row) => (!variant || row.variant_id === variant) && JSON.stringify(row.answers).toLowerCase().includes(search.toLowerCase())), [detail, variant, search]);
  const pager = useFactoryClientPagination("product-feedback-responses", responses.length, 20, `${selected || ""}:${search}:${variant}`);
  async function saveCampaign(value) { const saved = await factoryService.saveProductFeedbackCampaign(value); setEditor(null); await loadList(); await openCampaign(saved); onNotify?.({ title: "Campaign saved", tone: "success" }); }
  async function addVariant() { if (!variantName.trim()) return; await factoryService.saveProductFeedbackVariant({ campaign_id: selected, name: variantName.trim(), is_active: true }); setVariantName(""); await openCampaign({ id: selected }); }
  function copyLink(token) { navigator.clipboard?.writeText(publicUrl(token)); onNotify?.({ title: "Public link copied", tone: "success" }); }
  async function downloadQr(token, name = "product-feedback") { const href = await toDataURL(publicUrl(token), { width: 640, margin: 1 }); const link = document.createElement("a"); link.href = href; link.download = `${name}.png`; link.click(); }
  const CampaignModal = CampaignEditorModal;
  if (!selected) return <div className="space-y-5"><PageHeader section="Factory" title="Product Feedback" description="Create tasting campaigns and review anonymous product feedback." actions={canEdit ? <button className="btn-primary" type="button" onClick={() => setEditor({ name: "", status: "draft", default_language: "en", questions: sambalFeedbackTemplate })}><Plus size={15} /> Create Campaign</button> : null} /><FactoryFilterBar activeFilters={search ? [{ key: "search", label: "Search", value: search, onRemove: () => setSearch("") }] : []} onClear={() => setSearch("")}><Field label="Search"><input className={inputClass()} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search campaigns or events" /></Field></FactoryFilterBar><FactoryDataSurface><FactoryTable rows={campaigns} rowHover="mint" onRowClick={openCampaign} emptyTitle="No Product Feedback campaigns" emptyDescription="Create a campaign to collect tasting feedback." columns={[{ key: "name", label: "Campaign", render: (row) => <FactoryCellEntity name={row.name} code={row.event_label} /> }, { key: "period", label: "Period", render: (row) => [row.starts_on, row.ends_on].filter(Boolean).join(" – ") || <FactoryCellMuted>Open</FactoryCellMuted> }, { key: "responses", label: "Responses", align: "right", render: (row) => row.response_count || 0 }, { key: "status", label: "Status", render: (row) => <FactoryStatusBadge status={row.status === "live" ? "Active" : row.status === "closed" ? "Closed" : "Draft"} /> }, { key: "actions", label: "Actions", align: "right", render: (row) => <FactoryRowActions onView={() => openCampaign(row)} directActions={canEdit ? [{ label: "Edit campaign", onClick: () => editCampaign(row) }] : []} /> }]} /></FactoryDataSurface>{editor ? <CampaignModal campaign={editor} finishedGoods={list.finished_goods} onClose={() => setEditor(null)} onSave={saveCampaign} onNotify={onNotify} /> : null}</div>;
  const campaign = detail?.campaign || {}; const summary = detail?.summary || {};
  if (tab === "overview") return <CampaignOverview campaign={campaign} summary={summary} variants={detail?.variants || []} canEdit={canEdit} variantName={variantName} onVariantName={setVariantName} onAddVariant={addVariant} onCampaigns={() => { setSelected(null); setDetail(null); setSearch(""); }} onEdit={() => setEditor(campaign)} onTabChange={setTab} onCopy={copyLink} onDownload={downloadQr} />;
  return <div className="space-y-5"><PageHeader section="Factory" title={campaign.name || "Product Feedback"} description={campaign.event_label || "Tasting campaign"} actions={<div className="flex gap-2"><button className="btn-secondary" type="button" onClick={() => { setSelected(null); setDetail(null); setSearch(""); }}>Campaigns</button>{canEdit ? <button className="btn-primary" type="button" onClick={() => setEditor(campaign)}>Edit Campaign</button> : null}</div>} /><div className="flex border-b border-border"><Tabs value={tab} onChange={setTab} /></div>{tab === "overview" ? <><div className="grid gap-3 md:grid-cols-4"><FactorySummaryCard icon={ClipboardList} label="Responses" value={summary.responses || 0} /><FactorySummaryCard icon={Star} tone="success" label="Overall Rating" value={summary.overall_rating || "—"} /><FactorySummaryCard icon={ThumbsUp} tone="success" label="Would Buy" value={`${summary.would_buy_percent || 0}%`} /><FactorySummaryCard icon={QrCode} tone="info" label="Just right spiciness" value={`${summary.just_right_spiciness_percent || 0}%`} /></div><FactoryDataSurface><div className="space-y-4 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-semibold text-text-primary">Public feedback link</h2><p className="mt-1 text-sm text-text-secondary">Live campaigns can be shared by campaign or sample variant.</p></div><div className="flex gap-2"><button className="btn-secondary" type="button" onClick={() => copyLink(campaign.public_id)}><Copy size={15} /> Copy link</button><button className="btn-secondary" type="button" onClick={() => downloadQr(campaign.public_id, campaign.name)}><QrCode size={15} /> QR PNG</button><a className="btn-secondary" href={publicUrl(campaign.public_id)} target="_blank" rel="noreferrer"><Eye size={15} /> Preview</a></div></div><div className="rounded-lg border border-border bg-[var(--theme-subtle)] p-3 text-sm font-medium text-text-secondary break-all">{publicUrl(campaign.public_id)}</div><div className="border-t border-border pt-4"><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-semibold text-text-primary">Variants / samples</h2>{canEdit ? <div className="flex gap-2"><input className={`${inputClass()} h-9`} value={variantName} placeholder="Sambal A" onChange={(event) => setVariantName(event.target.value)} /><button type="button" className="btn-secondary h-9" onClick={addVariant}>Add variant</button></div> : null}</div>{detail?.variants?.length ? <div className="grid gap-2 md:grid-cols-2">{detail.variants.map((item) => <div className="flex items-center justify-between rounded-lg border border-border p-3" key={item.id}><span className="font-semibold text-text-primary">{item.name}</span><div className="flex gap-2"><button className="icon-btn" title="Copy variant link" type="button" onClick={() => copyLink(item.public_token)}><Link2 size={15} /></button><button className="icon-btn" title="Download variant QR" type="button" onClick={() => downloadQr(item.public_token, item.name)}><QrCode size={15} /></button><a className="icon-btn" title="Preview variant" href={publicUrl(item.public_token)} target="_blank" rel="noreferrer"><Eye size={15} /></a></div></div>)}</div> : <p className="text-sm text-text-secondary">No variants. This campaign uses one shared public link.</p>}</div></div></FactoryDataSurface></> : null}{tab === "form" ? <FormBuilder campaign={campaign} editable={canEdit} onSave={async (questions) => saveCampaign({ ...campaign, questions })} onNotify={onNotify} /> : null}{tab === "responses" ? <><FactoryFilterBar activeFilters={[search && { key: "search", label: "Search", value: search, onRemove: () => setSearch("") }, variant && { key: "variant", label: "Variant", value: detail.variants?.find((item) => item.id === variant)?.name || variant, onRemove: () => setVariant("") }].filter(Boolean)} onClear={() => { setSearch(""); setVariant(""); }}><Field label="Search"><input className={inputClass()} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search answers" /></Field><Field label="Variant"><SearchableSelect value={variant} placeholder="All" options={[{ value: "", label: "All" }, ...(detail.variants || []).map((item) => ({ value: item.id, label: item.name }))]} onChange={setVariant} /></Field></FactoryFilterBar><FactoryDataSurface><FactoryTable rows={responses.slice(pager.from, pager.to)} emptyTitle="No feedback responses" columns={[{ key: "submitted", label: "Submitted", render: (row) => formatFactoryDateTime(row.submitted_at) }, { key: "variant", label: "Variant", render: (row) => row.variant_name || <FactoryCellMuted>Campaign</FactoryCellMuted> }, { key: "rating", label: "Rating", render: (row) => row.answers?.overall_rating || "—" }, { key: "intent", label: "Purchase Intent", render: (row) => row.answers?.purchase_intent || "—" }, { key: "repeat", label: "Repeat", render: (row) => row.repeat_index > 1 ? `Possible repeat #${row.repeat_index}` : "—" }, { key: "actions", label: "Actions", align: "right", render: (row) => <FactoryRowActions onView={() => setResponse(row)} /> }]} /><FactoryPagination page={pager.page} pageSize={pager.pageSize} total={responses.length} onPageChange={pager.setPage} onPageSizeChange={pager.setPageSize} /></FactoryDataSurface></> : null}{editor ? <CampaignModal campaign={editor} finishedGoods={list.finished_goods} onClose={() => setEditor(null)} onSave={saveCampaign} onNotify={onNotify} /> : null}{response ? <ResponseModal response={response} onClose={() => setResponse(null)} /> : null}</div>;
  return <div className="space-y-5"><PageHeader section="Factory" title={campaign.name || "Product Feedback"} description={campaign.event_label || "Tasting campaign"} actions={<div className="flex gap-2"><button className="btn-secondary" type="button" onClick={() => { setSelected(null); setDetail(null); setSearch(""); }}>Campaigns</button>{canEdit ? <button className="btn-primary" type="button" onClick={() => setEditor(campaign)}>Edit Campaign</button> : null}</div>} /><div className="flex border-b border-border"><Tabs value={tab} onChange={setTab} /></div>{tab === "overview" ? <><div className="grid gap-3 md:grid-cols-4">{campaignSummaryCards(summary).filter((item) => item.key === "responses" || (item.value !== null && item.value !== undefined && item.value !== "—")).map((item) => <FactorySummaryCard key={item.key} icon={item.icon} tone={item.tone} label={item.label} value={item.value} />)}</div><FactoryDataSurface><div className="space-y-4 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-semibold text-text-primary">Public feedback link</h2><p className="mt-1 text-sm text-text-secondary">Live campaigns can be shared by campaign or sample variant.</p></div><div className="flex gap-2"><button className="btn-secondary" type="button" onClick={() => copyLink(campaign.public_id)}><Copy size={15} /> Copy link</button><button className="btn-secondary" type="button" onClick={() => downloadQr(campaign.public_id, campaign.name)}><QrCode size={15} /> QR PNG</button><a className="btn-secondary" href={publicUrl(campaign.public_id)} target="_blank" rel="noreferrer"><Eye size={15} /> Preview</a></div></div><div className="rounded-lg border border-border bg-[var(--theme-subtle)] p-3 text-sm font-medium text-text-secondary break-all">{publicUrl(campaign.public_id)}</div><div className="border-t border-border pt-4"><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-semibold text-text-primary">Variants / samples</h2>{canEdit ? <div className="flex gap-2"><input className={`${inputClass()} h-9`} value={variantName} placeholder="Sambal A" onChange={(event) => setVariantName(event.target.value)} /><button type="button" className="btn-secondary h-9" onClick={addVariant}>Add variant</button></div> : null}</div>{detail?.variants?.length ? <div className="grid gap-2 md:grid-cols-2">{detail.variants.map((item) => <div className="flex items-center justify-between rounded-lg border border-border p-3" key={item.id}><span className="font-semibold text-text-primary">{item.name}</span><div className="flex gap-2"><button className="icon-btn" title="Copy variant link" type="button" onClick={() => copyLink(item.public_token)}><Link2 size={15} /></button><button className="icon-btn" title="Download variant QR" type="button" onClick={() => downloadQr(item.public_token, item.name)}><QrCode size={15} /></button><a className="icon-btn" title="Preview variant" href={publicUrl(item.public_token)} target="_blank" rel="noreferrer"><Eye size={15} /></a></div></div>)}</div> : <p className="text-sm text-text-secondary">No variants. This campaign uses one shared public link.</p>}</div></div></FactoryDataSurface></> : null}{tab === "form" ? <FormBuilder campaign={campaign} editable={canEdit} onSave={async (questions) => saveCampaign({ ...campaign, questions })} onNotify={onNotify} /> : null}{tab === "responses" ? <><FactoryFilterBar activeFilters={[search && { key: "search", label: "Search", value: search, onRemove: () => setSearch("") }, variant && { key: "variant", label: "Variant", value: detail.variants?.find((item) => item.id === variant)?.name || variant, onRemove: () => setVariant("") }].filter(Boolean)} onClear={() => { setSearch(""); setVariant(""); }}><Field label="Search"><input className={inputClass()} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search answers" /></Field><Field label="Variant"><SearchableSelect value={variant} placeholder="All" options={[{ value: "", label: "All" }, ...(detail.variants || []).map((item) => ({ value: item.id, label: item.name }))]} onChange={setVariant} /></Field></FactoryFilterBar><FactoryDataSurface><FactoryTable rows={responses.slice(pager.from, pager.to)} emptyTitle="No feedback responses" columns={[{ key: "submitted", label: "Submitted", render: (row) => formatFactoryDateTime(row.submitted_at) }, { key: "variant", label: "Variant", render: (row) => row.variant_name || <FactoryCellMuted>Campaign</FactoryCellMuted> }, { key: "rating", label: "Rating", render: (row) => row.answers?.overall_rating || "—" }, { key: "intent", label: "Purchase Intent", render: (row) => row.answers?.purchase_intent || "—" }, { key: "repeat", label: "Repeat", render: (row) => row.repeat_index > 1 ? `Possible repeat #${row.repeat_index}` : "—" }, { key: "actions", label: "Actions", align: "right", render: (row) => <FactoryRowActions onView={() => setResponse(row)} /> }]} /><FactoryPagination page={pager.page} pageSize={pager.pageSize} total={responses.length} onPageChange={pager.setPage} onPageSizeChange={pager.setPageSize} /></FactoryDataSurface></> : null}{editor ? <CampaignModal campaign={editor} finishedGoods={list.finished_goods} onClose={() => setEditor(null)} onSave={saveCampaign} onNotify={onNotify} /> : null}{response ? <ResponseModal response={response} onClose={() => setResponse(null)} /> : null}</div>;
}

function Tabs({ value, onChange }) { return <>{["overview", "form", "responses"].map((item) => <button key={item} type="button" className={`px-4 py-3 text-sm font-semibold capitalize ${value === item ? "border-b-2 border-primary text-primary" : "text-text-secondary"}`} onClick={() => onChange(item)}>{item}</button>)}</>; }
const languages = [{ key: "en", label: "EN" }, { key: "zh", label: "中文" }, { key: "ms", label: "BM" }];
const types = [
  { value: "single_choice", label: "Single Choice" },
  { value: "multi_choice", label: "Multiple Choice" },
  { value: "rating", label: "Rating" },
  { value: "price_choice", label: "Price" },
  { value: "short_text", label: "Short Answer" },
  { value: "image_choice", label: "Image Choice" },
];
const emptyQuestion = (order) => ({ key: `question_${Date.now()}`, label_en: "New question", label_zh: "", label_ms: "", helper_en: "", helper_zh: "", helper_ms: "", type: "short_text", required: false, options: [], order });
const kpiIcon = { overall_rating: Star, purchase_intent: ThumbsUp, taste_spiciness: ClipboardList, price_acceptance: QrCode, generic_choice_distribution: ClipboardList };
export function campaignSummaryCards(summary) {
  return [
    { key: "responses", icon: ClipboardList, label: "Responses", value: summary.responses || 0, tone: "neutral" },
    ...(summary.kpis || []).map((item) => ({ key: item.question_key || item.role, icon: kpiIcon[item.role] || ClipboardList, label: item.label, value: item.value, tone: item.tone || "info" })),
  ];
}

function CampaignOverview({ campaign, summary, variants, canEdit, variantName, onVariantName, onAddVariant, onCampaigns, onEdit, onTabChange, onCopy, onDownload }) {
  const cards = campaignSummaryCards(summary).filter((item) => item.key === "responses" || (item.value !== null && item.value !== undefined && item.value !== "—"));
  return <div className="space-y-5"><PageHeader section="Factory" title={campaign.name || "Product Feedback"} description={campaign.event_label || "Tasting campaign"} actions={<div className="flex gap-2"><button className="btn-secondary" type="button" onClick={onCampaigns}>Campaigns</button>{canEdit ? <button className="btn-primary" type="button" onClick={onEdit}>Edit Campaign</button> : null}</div>} /><div className="flex border-b border-border"><Tabs value="overview" onChange={onTabChange} /></div><div className="grid gap-3 md:grid-cols-4">{cards.map((item) => <FactorySummaryCard key={item.key} icon={item.icon} tone={item.tone} label={item.label} value={item.value} />)}</div><FactoryDataSurface><div className="space-y-4 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-sm font-semibold text-text-primary">Public feedback link</h2><p className="mt-1 text-sm text-text-secondary">Live campaigns can be shared by campaign or sample variant.</p></div><div className="flex gap-2"><button className="btn-secondary" type="button" onClick={() => onCopy(campaign.public_id)}><Copy size={15} /> Copy link</button><button className="btn-secondary" type="button" onClick={() => onDownload(campaign.public_id, campaign.name)}><QrCode size={15} /> QR PNG</button><a className="btn-secondary" href={publicUrl(campaign.public_id)} target="_blank" rel="noreferrer"><Eye size={15} /> Preview</a></div></div><div className="rounded-lg border border-border bg-[var(--theme-subtle)] p-3 text-sm font-medium text-text-secondary break-all">{publicUrl(campaign.public_id)}</div><div className="border-t border-border pt-4"><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-semibold text-text-primary">Variants / samples</h2>{canEdit ? <div className="flex gap-2"><input className={`${inputClass()} h-9`} value={variantName} placeholder="Sambal A" onChange={(event) => onVariantName(event.target.value)} /><button type="button" className="btn-secondary h-9" onClick={onAddVariant}>Add variant</button></div> : null}</div>{variants.length ? <div className="grid gap-2 md:grid-cols-2">{variants.map((item) => <div className="flex items-center justify-between rounded-lg border border-border p-3" key={item.id}><span className="font-semibold text-text-primary">{item.name}</span><div className="flex gap-2"><button className="icon-btn" title="Copy variant link" type="button" onClick={() => onCopy(item.public_token)}><Link2 size={15} /></button><button className="icon-btn" title="Download variant QR" type="button" onClick={() => onDownload(item.public_token, item.name)}><QrCode size={15} /></button><a className="icon-btn" title="Preview variant" href={publicUrl(item.public_token)} target="_blank" rel="noreferrer"><Eye size={15} /></a></div></div>)}</div> : <p className="text-sm text-text-secondary">No variants. This campaign uses one shared public link.</p>}</div></div></FactoryDataSurface></div>;
}


function CampaignModal({ campaign, finishedGoods, onClose, onSave, onNotify }) {
  const [form, setForm] = useState(() => ({ ...campaign, questions: campaign.questions?.length ? campaign.questions : sambalFeedbackTemplate, content: campaign.content || { title: { en: campaign.name || "", zh: "", ms: "" }, description: { en: "", zh: "", ms: "" }, intro_title: { en: "", zh: "", ms: "" }, intro_body: { en: "", zh: "", ms: "" }, thank_you_title: { en: "Thank you", zh: "谢谢您的反馈", ms: "Terima kasih" }, thank_you_body: { en: campaign.thank_you_en || "", zh: campaign.thank_you_zh || "", ms: "" } }, branding: campaign.branding || {} }));
  const [language, setLanguage] = useState("en"); const [uploading, setUploading] = useState(""); const [translating, setTranslating] = useState(false);
  const updateContent = (field, value) => setForm((current) => ({ ...current, content: { ...current.content, [field]: { ...(current.content?.[field] || {}), [language]: value } } }));
  const upload = async (event, field) => { const file = event.target.files?.[0]; if (!file) return; setUploading(field); try { const image = await factoryService.uploadProductFeedbackImage(file, form, field); setForm((current) => ({ ...current, branding: { ...current.branding, [field]: image.publicUrl } })); } finally { setUploading(""); } };
  const translateContent = async () => { const fields = ["title", "description", "intro_title", "intro_body", "thank_you_title", "thank_you_body"]; const targets = languages.filter((item) => item.key !== language).map((item) => item.key); const units = fields.flatMap((field) => { const source = form.content?.[field]?.[language] || (field === "title" && language === "en" ? form.name : ""); const missing = targets.filter((target) => !form.content?.[field]?.[target]); return String(source || "").trim() && missing.length ? [{ id: `content:${field}`, source, targets: missing }] : []; }); if (!units.length) return; setTranslating(true); try { const results = await factoryService.translateProductFeedbackContent({ sourceLanguage: language, units }); setForm((current) => { const next = structuredClone(current); results.forEach((result) => { const field = String(result.id).split(":")[1]; next.content[field] = { ...(next.content[field] || {}), [result.language]: result.text }; }); return next; }); } catch (error) { onNotify?.({ title: "AI translation unavailable", message: error.message, tone: "error" }); } finally { setTranslating(false); } };
  return <Modal title={form.id ? "Edit Campaign" : "Create Campaign"} onClose={onClose} size="lg"><form className="space-y-4" onSubmit={(event) => { event.preventDefault(); onSave(form); }}><div className="grid gap-3 md:grid-cols-2"><Field label="Campaign name"><input required className={inputClass()} value={form.name || ""} onChange={(event) => setForm({ ...form, name: event.target.value, content: { ...form.content, title: { ...(form.content?.title || {}), en: event.target.value } } })} /></Field><Field label="Finished Good"><SearchableSelect value={form.finished_good_id || ""} placeholder="Optional" options={[{ value: "", label: "None" }, ...finishedGoods.map((item) => ({ value: item.id, label: `${item.code || ""} ${item.name}` }))]} onChange={(finished_good_id) => setForm({ ...form, finished_good_id })} /></Field><Field label="Event / location"><input className={inputClass()} value={form.event_label || ""} onChange={(event) => setForm({ ...form, event_label: event.target.value })} /></Field><Field label="Status"><SearchableSelect value={form.status || "draft"} options={[{ value: "draft", label: "Draft" }, { value: "live", label: "Live" }, { value: "closed", label: "Closed" }]} onChange={(status) => setForm({ ...form, status })} /></Field><Field label="Start date"><input type="date" className={inputClass()} value={form.starts_on || ""} onChange={(event) => setForm({ ...form, starts_on: event.target.value })} /></Field><Field label="End date"><input type="date" className={inputClass()} value={form.ends_on || ""} onChange={(event) => setForm({ ...form, ends_on: event.target.value })} /></Field></div><section className="border-t border-border pt-4"><div className="mb-3 flex items-center justify-between gap-2"><h3 className="text-sm font-bold text-text-primary">Public content</h3><div className="flex items-center gap-2"><button type="button" className="btn-secondary h-8" disabled={translating} onClick={translateContent}>{translating ? "Translating…" : "AI Translate missing"}</button><LanguageTabs value={language} onChange={setLanguage} /></div></div><div className="grid gap-3"><Field label="Campaign title"><input className={inputClass()} value={form.content?.title?.[language] || ""} onChange={(event) => updateContent("title", event.target.value)} /></Field><Field label="Description"><textarea className={inputClass()} value={form.content?.description?.[language] || ""} onChange={(event) => updateContent("description", event.target.value)} /></Field><Field label="Intro title"><input className={inputClass()} value={form.content?.intro_title?.[language] || ""} onChange={(event) => updateContent("intro_title", event.target.value)} /></Field><Field label="Intro body"><textarea className={inputClass()} value={form.content?.intro_body?.[language] || ""} onChange={(event) => updateContent("intro_body", event.target.value)} /></Field><Field label="Thank-you title"><input className={inputClass()} value={form.content?.thank_you_title?.[language] || ""} onChange={(event) => updateContent("thank_you_title", event.target.value)} /></Field><Field label="Thank-you body"><textarea className={inputClass()} value={form.content?.thank_you_body?.[language] || ""} onChange={(event) => updateContent("thank_you_body", event.target.value)} /></Field></div></section><section className="border-t border-border pt-4"><h3 className="mb-3 text-sm font-bold text-text-primary">Campaign branding</h3><div className="grid gap-3 md:grid-cols-2"><Field label="Primary color"><input type="color" className="h-10 w-full rounded-lg border border-border bg-surface p-1" value={form.branding?.primary_color || "#168546"} onChange={(event) => setForm((current) => ({ ...current, branding: { ...current.branding, primary_color: event.target.value } }))} /></Field><Field label="Accent color"><input type="color" className="h-10 w-full rounded-lg border border-border bg-surface p-1" value={form.branding?.accent_color || "#0f6e3b"} onChange={(event) => setForm((current) => ({ ...current, branding: { ...current.branding, accent_color: event.target.value } }))} /></Field>{[["logo_url", "Logo"], ["hero_url", "Hero / poster"], ["thank_you_image_url", "Thank-you artwork"]].map(([field, label]) => <Field key={field} label={label}><div className="flex gap-2"><input className={inputClass()} value={form.branding?.[field] || ""} onChange={(event) => setForm((current) => ({ ...current, branding: { ...current.branding, [field]: event.target.value } }))} placeholder="Image URL" /><label className="btn-secondary shrink-0 cursor-pointer">{uploading === field ? "Uploading…" : "Upload"}<input className="sr-only" type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => upload(event, field)} /></label></div></Field>)}</div></section><div className="flex justify-end gap-2 pt-2"><button type="button" className="btn-secondary" onClick={onClose}>Cancel</button><button className="btn-primary" type="submit">Save Campaign</button></div></form></Modal>;
}

export function CampaignEditorModal({ campaign, finishedGoods, onClose, onSave, onNotify }) {
  const [form, setForm] = useState(() => productFeedbackCampaignEditorState(campaign));
  const [language, setLanguage] = useState("en");
  const [uploading, setUploading] = useState("");
  const [uploadError, setUploadError] = useState(null);
  const [saveError, setSaveError] = useState("");
  const [saving, setSaving] = useState(false);
  const [translating, setTranslating] = useState(false);
  const updateContent = (field, value) => setForm((current) => ({ ...current, content: { ...current.content, [field]: { ...(current.content?.[field] || {}), [language]: value } } }));
  const updateBranding = (field, value) => setForm((current) => ({ ...current, branding: { ...current.branding, [field]: value } }));
  const upload = async (event, field) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setUploading(field); setUploadError(null);
    try {
      // Keep the persisted asset intact until this campaign save succeeds.
      const image = await factoryService.uploadProductFeedbackImage(file, form, field);
      updateBranding(field, image.publicUrl);
    } catch (error) {
      const message = error.message || "Unable to upload this image.";
      setUploadError({ field, message });
      onNotify?.({ title: "Image upload failed", message, tone: "error" });
    } finally { setUploading(""); }
  };
  const translateContent = async () => {
    const fields = ["title", "description", "intro_title", "intro_body", "thank_you_title", "thank_you_body"];
    const targets = languages.filter((item) => item.key !== language).map((item) => item.key);
    const units = fields.flatMap((field) => {
      const source = form.content?.[field]?.[language] || (field === "title" && language === "en" ? form.name : "");
      const missing = targets.filter((target) => !form.content?.[field]?.[target]);
      return String(source || "").trim() && missing.length ? [{ id: `content:${field}`, source, targets: missing }] : [];
    });
    if (!units.length) return;
    setTranslating(true);
    try {
      const results = await factoryService.translateProductFeedbackContent({ sourceLanguage: language, units });
      setForm((current) => {
        const next = structuredClone(current);
        results.forEach((result) => {
          const field = String(result.id).split(":")[1];
          next.content[field] = { ...(next.content[field] || {}), [result.language]: result.text };
        });
        return next;
      });
    } catch (error) {
      onNotify?.({ title: "AI translation unavailable", message: error.message, tone: "error" });
    } finally { setTranslating(false); }
  };
  const save = async (event) => {
    event.preventDefault();
    setSaving(true); setSaveError("");
    try {
      // Question changes remain owned by Form Builder. Branding/settings saves must not
      // trip immutable response-snapshot protection on a live campaign.
      const { questions, ...campaignSettings } = form;
      await onSave(form.id ? campaignSettings : form);
    }
    catch (error) {
      const message = error.message || "Unable to save campaign branding.";
      setSaveError(message);
      onNotify?.({ title: "Campaign save failed", message, tone: "error" });
    } finally { setSaving(false); }
  };
  return <Modal title={form.id ? "Edit Campaign" : "Create Campaign"} onClose={onClose} size="lg" footer={<><button type="button" className="btn-secondary" disabled={saving} onClick={onClose}>Cancel</button><button className="btn-primary" form="product-feedback-campaign-form" disabled={saving || Boolean(uploading)} type="submit">{saving ? "Saving…" : "Save Campaign"}</button></>}><form id="product-feedback-campaign-form" className="space-y-4" onSubmit={save}><div className="grid gap-3 md:grid-cols-2"><Field label="Campaign name"><input required className={inputClass()} value={form.name || ""} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value, content: { ...current.content, title: { ...(current.content?.title || {}), en: event.target.value } } }))} /></Field><Field label="Finished Good"><SearchableSelect value={form.finished_good_id || ""} placeholder="Optional" options={[{ value: "", label: "None" }, ...finishedGoods.map((item) => ({ value: item.id, label: `${item.code || ""} ${item.name}` }))]} onChange={(finished_good_id) => setForm((current) => ({ ...current, finished_good_id }))} /></Field><Field label="Event / location"><input className={inputClass()} value={form.event_label || ""} onChange={(event) => setForm((current) => ({ ...current, event_label: event.target.value }))} /></Field><Field label="Status"><SearchableSelect value={form.status || "draft"} options={[{ value: "draft", label: "Draft" }, { value: "live", label: "Live" }, { value: "closed", label: "Closed" }]} onChange={(status) => setForm((current) => ({ ...current, status }))} /></Field><Field label="Start date"><input type="date" className={inputClass()} value={form.starts_on || ""} onChange={(event) => setForm((current) => ({ ...current, starts_on: event.target.value }))} /></Field><Field label="End date"><input type="date" className={inputClass()} value={form.ends_on || ""} onChange={(event) => setForm((current) => ({ ...current, ends_on: event.target.value }))} /></Field></div><section className="border-t border-border pt-4"><div className="mb-3 flex items-center justify-between gap-2"><h3 className="text-sm font-bold text-text-primary">Public content</h3><div className="flex items-center gap-2"><button type="button" className="btn-secondary h-8" disabled={translating} onClick={translateContent}>{translating ? "Translating…" : "AI Translate missing"}</button><LanguageTabs value={language} onChange={setLanguage} /></div></div><div className="grid gap-3"><Field label="Campaign title"><input className={inputClass()} value={form.content?.title?.[language] || ""} onChange={(event) => updateContent("title", event.target.value)} /></Field><Field label="Description"><textarea className={inputClass()} value={form.content?.description?.[language] || ""} onChange={(event) => updateContent("description", event.target.value)} /></Field><Field label="Intro title"><input className={inputClass()} value={form.content?.intro_title?.[language] || ""} onChange={(event) => updateContent("intro_title", event.target.value)} /></Field><Field label="Intro body"><textarea className={inputClass()} value={form.content?.intro_body?.[language] || ""} onChange={(event) => updateContent("intro_body", event.target.value)} /></Field><Field label="Thank-you title"><input className={inputClass()} value={form.content?.thank_you_title?.[language] || ""} onChange={(event) => updateContent("thank_you_title", event.target.value)} /></Field><Field label="Thank-you body"><textarea className={inputClass()} value={form.content?.thank_you_body?.[language] || ""} onChange={(event) => updateContent("thank_you_body", event.target.value)} /></Field></div></section><section className="border-t border-border pt-4"><h3 className="mb-3 text-sm font-bold text-text-primary">Campaign branding</h3><div className="grid gap-3 md:grid-cols-2"><Field label="Primary color"><input type="color" className="h-10 w-full rounded-lg border border-border bg-surface p-1" value={form.branding?.primary_color || "#168546"} onChange={(event) => updateBranding("primary_color", event.target.value)} /></Field><Field label="Accent color"><input type="color" className="h-10 w-full rounded-lg border border-border bg-surface p-1" value={form.branding?.accent_color || "#0f6e3b"} onChange={(event) => updateBranding("accent_color", event.target.value)} /></Field><CampaignBrandingImageField label="Logo" field="logo_url" value={form.branding?.logo_url} uploading={uploading === "logo_url"} error={uploadError?.field === "logo_url" ? uploadError.message : ""} onUpload={upload} onRemove={updateBranding} /><CampaignBrandingImageField label="Hero / poster" field="hero_url" value={form.branding?.hero_url} uploading={uploading === "hero_url"} error={uploadError?.field === "hero_url" ? uploadError.message : ""} onUpload={upload} onRemove={updateBranding} /><CampaignBrandingImageField label="Thank-you artwork" field="thank_you_image_url" value={form.branding?.thank_you_image_url} uploading={uploading === "thank_you_image_url"} error={uploadError?.field === "thank_you_image_url" ? uploadError.message : ""} onUpload={upload} onRemove={updateBranding} /></div></section>{saveError ? <p className="rounded-lg border border-danger/30 bg-danger/10 px-3 py-2 text-sm text-danger" role="alert">{saveError}</p> : null}</form></Modal>;
}

function CampaignBrandingImageField({ label, field, value, uploading, error, onUpload, onRemove }) {
  return <Field label={label}><div className="space-y-2 rounded-lg border border-border bg-[var(--theme-subtle)] p-2.5">{value ? <img className="h-28 w-full rounded-md border border-border bg-surface object-cover" src={value} alt={`${label} preview`} /> : <div className="flex h-28 items-center justify-center rounded-md border border-dashed border-border bg-surface text-xs font-medium text-text-secondary">No image uploaded</div>}<div className="flex items-center gap-2"><label className="btn-secondary cursor-pointer">{uploading ? "Uploading…" : value ? "Replace" : "Upload"}<input className="sr-only" type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading} onChange={(event) => onUpload(event, field)} /></label>{value ? <button type="button" className="btn-secondary" disabled={uploading} onClick={() => onRemove(field, null)}>Remove</button> : null}</div>{error ? <p className="text-xs font-medium text-danger" role="alert">{error}</p> : null}</div></Field>;
}

function FormBuilder({ campaign, editable, onSave, onNotify }) {
  const [questions, setQuestions] = useState(campaign.questions || []); const [editing, setEditing] = useState(null); const [saving, setSaving] = useState(false);
  const update = (index, value) => setQuestions((current) => current.map((item, itemIndex) => itemIndex === index ? value : item));
  const move = (index, change) => { const target = index + change; if (target < 0 || target >= questions.length) return; const next = [...questions]; [next[index], next[target]] = [next[target], next[index]]; setQuestions(next.map((item, order) => ({ ...item, order: order + 1 }))); };
  const save = async () => { setSaving(true); try { await onSave(questions); } finally { setSaving(false); } };
  return <FactoryDataSurface><div className="space-y-2 p-3">{questions.map((question, index) => <div className="flex items-center gap-3 rounded-lg border border-border px-3 py-2" key={question.key}><span className="w-6 text-xs font-semibold text-text-muted">{index + 1}</span><button type="button" className="min-w-0 flex-1 text-left" onClick={() => editable && setEditing(index)}><span className="block truncate text-sm font-semibold text-text-primary">{question.label_en}</span><span className="block text-xs text-text-secondary">{question.type.replace("_", " ")} · {question.required ? "Required" : "Optional"} · {question.options?.length || 0} options</span></button>{editable ? <div className="flex shrink-0 gap-1"><button className="icon-btn" type="button" title="Edit question" onClick={() => setEditing(index)}><Pencil size={15} /></button><button className="icon-btn" type="button" title="Move up" onClick={() => move(index, -1)}>↑</button><button className="icon-btn" type="button" title="Move down" onClick={() => move(index, 1)}>↓</button><button className="icon-btn" type="button" title="Duplicate" onClick={() => setQuestions((current) => [...current, { ...question, key: `${question.key}_copy_${Date.now()}`, order: current.length + 1 }])}>⧉</button><button className="icon-btn text-danger" type="button" title="Delete" onClick={() => setQuestions((current) => current.filter((_, itemIndex) => itemIndex !== index))}><Trash2 size={15} /></button></div> : null}</div>)}{editable ? <div className="flex justify-between pt-3"><button className="btn-secondary" type="button" onClick={() => { setQuestions((current) => [...current, emptyQuestion(current.length + 1)]); setEditing(questions.length); }}>Add question</button><button className="btn-primary" disabled={saving} type="button" onClick={save}>{saving ? "Saving…" : "Save form"}</button></div> : null}</div>{editing !== null ? <QuestionEditor question={questions[editing]} onClose={() => setEditing(null)} onSave={(question) => { update(editing, question); setEditing(null); }} onNotify={onNotify} /> : null}</FactoryDataSurface>;
}

function QuestionEditor({ question, onClose, onSave, onNotify }) {
  const [draft, setDraft] = useState(() => ({ ...question, options: question.options || [] })); const [language, setLanguage] = useState("en"); const [translating, setTranslating] = useState(false); const [draggedOption, setDraggedOption] = useState(null); const supportsOptions = draft.type !== "short_text";
  const translationComplete = languages.map(({ key, label }) => ({ key, label, complete: Boolean(draft[`label_${key}`]) && draft.options.every((option) => !option[`label_en`] || Boolean(option[`label_${key}`])) }));
  const setField = (field, value) => setDraft((current) => ({ ...current, [field]: value })); const setOption = (index, field, value) => setDraft((current) => ({ ...current, options: current.options.map((item, itemIndex) => itemIndex === index ? { ...item, [field]: value } : item) }));
  const changeType = (type) => { if (type === draft.type) return; if (draft.options.length && !window.confirm("Changing question type may discard incompatible option settings. Continue?")) return; setField("type", type); };
  const moveOption = (from, to) => { if (from === to || to < 0 || to >= draft.options.length) return; setDraft((current) => { const options = [...current.options]; const [item] = options.splice(from, 1); options.splice(to, 0, item); return { ...current, options }; }); };
  const translate = async () => { const units = []; const targets = languages.filter((item) => item.key !== language).map((item) => item.key); [["label", draft[`label_${language}`]], ["helper", draft[`helper_${language}`]]].forEach(([kind, source]) => { if (String(source || "").trim()) units.push({ id: `question:${kind}`, source, targets: targets.filter((target) => !draft[`${kind}_${target}`]) }); }); draft.options.forEach((option, index) => { const source = option[`label_${language}`]; if (String(source || "").trim()) units.push({ id: `option:${index}`, source, targets: targets.filter((target) => !option[`label_${target}`]) }); }); if (!units.length) return; setTranslating(true); try { const results = await factoryService.translateProductFeedbackContent({ sourceLanguage: language, units }); setDraft((current) => { const next = structuredClone(current); results.forEach((result) => { const [scope, index] = String(result.id).split(":"); if (scope === "question") next[`${index}_${result.language}`] = result.text; if (scope === "option" && next.options[Number(index)]) next.options[Number(index)][`label_${result.language}`] = result.text; }); return next; }); } catch (error) { onNotify?.({ title: "AI translation unavailable", message: error.message, tone: "error" }); } finally { setTranslating(false); } };
  return <Modal title="Edit question" onClose={onClose} size="lg"><div className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-2"><LanguageTabs value={language} onChange={setLanguage} /><div className="flex items-center gap-2"><span className="text-xs font-semibold text-text-secondary">{translationComplete.map((item) => `${item.label} ${item.complete ? "✓" : "○"}`).join(" · ")}</span><button type="button" className="btn-secondary" disabled={translating} onClick={translate}>{translating ? "Translating…" : "AI Translate missing"}</button></div></div><div className="grid gap-3 md:grid-cols-2"><Field label="Question"><input required className={inputClass()} value={draft[`label_${language}`] || ""} onChange={(event) => setField(`label_${language}`, event.target.value)} /></Field><Field label="Question type"><CompactSelect value={draft.type} options={types} ariaLabel="Question type" onChange={changeType} /></Field></div><Field label="Helper text"><textarea className={inputClass()} value={draft[`helper_${language}`] || ""} onChange={(event) => setField(`helper_${language}`, event.target.value)} /></Field><label className="flex items-center gap-2 text-sm font-semibold text-text-primary"><input type="checkbox" checked={Boolean(draft.required)} onChange={(event) => setField("required", event.target.checked)} /> Required</label>{draft.type === "multi_choice" ? <Field label="Minimum selections"><input className={inputClass()} type="number" min="1" value={draft.min_selections || 1} onChange={(event) => setField("min_selections", Math.max(Number(event.target.value || 1), 1))} /></Field> : null}{supportsOptions ? <section className="space-y-2 border-t border-border pt-4"><div className="flex items-center justify-between"><h3 className="text-sm font-bold text-text-primary">Options</h3><button className="btn-secondary" type="button" onClick={() => setField("options", [...draft.options, { value: `option_${draft.options.length + 1}`, label_en: "New option", label_zh: "", label_ms: "", image_url: "", ...(draft.type === "price_choice" ? { amount: null, currency: "MYR", display_label: "New option" } : {}) }])}>Add option</button></div>{draft.options.map((option, index) => <div draggable onDragStart={() => setDraggedOption(index)} onDragOver={(event) => event.preventDefault()} onDrop={() => { moveOption(draggedOption, index); setDraggedOption(null); }} className="grid cursor-grab gap-2 rounded-lg border border-border p-2 md:grid-cols-[auto_1fr_1fr_auto]" key={`${option.value}-${index}`}><span className="self-center text-xs font-bold text-text-muted" title="Drag to reorder">⋮⋮</span><input className={inputClass()} value={option[`label_${language}`] || ""} placeholder={`Label (${language.toUpperCase()})`} onChange={(event) => setOption(index, `label_${language}`, event.target.value)} />{draft.type === "image_choice" ? <input className={inputClass()} value={option.image_url || ""} placeholder="Image URL" onChange={(event) => setOption(index, "image_url", event.target.value)} /> : draft.type === "price_choice" ? <div className="grid grid-cols-2 gap-2"><input className={inputClass()} type="number" min="0" step="0.01" value={option.amount ?? ""} placeholder="Amount" onChange={(event) => setOption(index, "amount", event.target.value === "" ? null : Number(event.target.value))} /><input className={inputClass()} value={option.currency || "MYR"} placeholder="Currency" onChange={(event) => setOption(index, "currency", event.target.value.toUpperCase())} /></div> : <span className="self-center text-xs text-text-secondary">{option.value !== (option.label_en || option.value) ? `Value: ${option.value}` : ""}</span>}<div className="flex gap-1"><button className="icon-btn" title="Move option up" type="button" onClick={() => moveOption(index, index - 1)}>↑</button><button className="icon-btn" title="Move option down" type="button" onClick={() => moveOption(index, index + 1)}>↓</button><button className="icon-btn text-danger" title="Delete option" type="button" onClick={() => setField("options", draft.options.filter((_, optionIndex) => optionIndex !== index))}><Trash2 size={15} /></button></div></div>)}</section> : null}<div className="flex justify-end gap-2"><button className="btn-secondary" type="button" onClick={onClose}>Cancel</button><button className="btn-primary" type="button" onClick={() => onSave(draft)}>Save question</button></div></div></Modal>;
}

function LanguageTabs({ value, onChange }) { return <div className="inline-flex rounded-lg border border-border p-1">{languages.map((item) => <button key={item.key} className={`rounded-md px-2.5 py-1 text-xs font-bold ${value === item.key ? "bg-[var(--theme-subtle)] text-primary" : "text-text-secondary"}`} type="button" onClick={() => onChange(item.key)}>{item.label}</button>)}</div>; }
function ResponseModal({ response, onClose }) { const questions = response.questions_snapshot || []; return <Modal title="Feedback response" onClose={onClose}><div className="space-y-4"><FactoryEvidenceHeader title={response.variant_name || "Campaign response"} subtitle={formatFactoryDateTime(response.submitted_at)} status={response.repeat_index > 1 ? { label: `Possible repeat #${response.repeat_index}`, tone: "warning" } : null} /><FactoryEvidenceSection title="Answers"><FactoryEvidenceGrid items={questions.map((question) => ({ label: question.label_en, value: displayAnswer(response.answers?.[question.key]), fullWidth: question.type === "short_text" }))} /></FactoryEvidenceSection></div></Modal>; }
